@Component("category-handler")
@ProcessingGroup("category-processing-group")
public class CategoryEventHandler {
	
	// core constructor
	CategoryEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateCategoryEvent
     */
    @EventHandler
    public void handle( CreateCategoryEvent event) {
        entityManager.persist(new Category(event.getCategoryId(), event.getName(), event.getSlug(), event.getPosition(), event.getAsActive(), event.getCatalog(), event.getParentCategory(), event.getSubcategories(), event.getProducts()));
    }

    /*
     * @param	event UpdateCategoryEvent
     */
    @EventHandler
    public Category handle( UpdateCategoryEvent event) {
    	entityManager.merge(new Category(event.getCategoryId(), event.getName(), event.getSlug(), event.getPosition(), event.getAsActive(), event.getCatalog(), event.getParentCategory(), event.getSubcategories(), event.getProducts()));
    }
    
    /*
     * @param	event DeleteCategoryEvent
     */
    @EventHandler
    public void on( DeleteCategoryEvent event) {
    	Category entity = new Category();
   
    	// ------------------------------------------
    	// apply the CategoryId
    	// ------------------------------------------
    	entity.setCategoryId( event.getCategoryId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final CategoryRepository categoryEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(CategoryEventHandler.class.getName());

}
